      kind: this.kind,
      owner: this.owner,
      keys: this.keys,
      status: this.status,
      requests: this.requests,
      bytesFetched: this.bytesFetched,
      bytesPlanned: this.bytesPlanned,
      bytesExpected: this.bytesExpected,
      bytesTotal,
      bytesPerSecond,
      remainingMs,
      cacheHits: this.cacheHits,
      chunks: this.chunks,
